-- GenZnect hosted verification: metadata only, no application rows or writes.
-- Run against project orhoolcpcbihfrbkpioz in your existing trusted SQL session.
-- Transaction is explicitly read-only. Share the JSON result, never connection credentials.
BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '30s';
SELECT jsonb_pretty(jsonb_build_object(
 'database', current_database(),
 'missing_expected_tables', (SELECT coalesce(jsonb_agg(name), '[]') FROM unnest(ARRAY['application_history','applications','campus_announcements','communities','community_comments','community_members','community_posts','community_reactions','community_resources','ecosystem_activity','event_registrations','events','founder_profiles','mentor_connections','mentor_profiles','mentor_sessions','notifications','opportunities','organizations','posts','profiles','project_activity','project_code_redemptions','project_files','project_invite_codes','project_members','project_tasks','projects','saved_opportunities','space_join_requests','student_details','student_preferences','support_reports','university_connection_requests','university_domains','university_student_invitations','university_student_memberships','workspace_invitations']) name WHERE to_regclass('public.' || name) IS NULL),
 'missing_expected_functions', (SELECT coalesce(jsonb_agg(name), '[]') FROM unnest(ARRAY['accept_university_invitation','assign_community_member','assign_community_member_by_email','assign_project_member','assign_project_member_by_email','can_manage_university','cancel_university_invitation','create_community','create_project','eco_activity','eco_announcement','eco_applicant_summary','eco_applicants','eco_application_activity','eco_campus_invitation_decide','eco_campus_invitations','eco_campus_invite','eco_campus_progress','eco_campus_requests','eco_code_accept','eco_code_create','eco_code_preview','eco_code_revoke','eco_connections','eco_context','eco_domain_save','eco_eligible','eco_event_attending','eco_event_save','eco_file_activity','eco_invitation_cancel','eco_invitation_decide','eco_invitation_guard','eco_invite','eco_join_request','eco_manager','eco_member_remove','eco_membership_scope','eco_mentor_decide','eco_mentor_profile','eco_mentor_request','eco_mentor_session','eco_opportunity_save','eco_portfolio','eco_portfolio_projects','eco_relationship_directory','eco_request_decide','eco_scope_allowed','eco_space_guard','eco_space_owner','eco_space_save','eco_space_visible','eco_task_save','eco_university_connect','eco_university_decide','enforce_organization_verified_change','enforce_post_review_fields','enforce_profile_identity','enforce_profile_role_change','enroll_university_student','finish_onboarding','handle_new_user','is_community_captain','is_platform_admin','is_project_head','list_space_member_names','list_university_students','protect_context_owner','protect_legacy_student_university','protect_official_organization','revoke_university_student','set_updated_at','update_student_workspace_profile','workspace_application_status','workspace_applied','workspace_apply','workspace_audience','workspace_create','workspace_directory','workspace_invite','workspace_join','workspace_member','workspace_notify','workspace_post','workspace_publish','workspace_react','workspace_ready','workspace_refresh_reminders','workspace_register','workspace_resource','workspace_save','workspace_stats','workspace_task','workspace_university_update']) name WHERE NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=name)),
 'tables_rls', (SELECT jsonb_agg(jsonb_build_object('table', c.relname, 'rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),
 'profile_columns', (SELECT jsonb_agg(jsonb_build_object('column',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default)) FROM information_schema.columns WHERE table_schema='public' AND table_name='profiles'),
 'roles', (SELECT jsonb_agg(jsonb_build_object('type',t.typname,'value',e.enumlabel)) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public'),
 'new_user_triggers', (SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) FROM pg_trigger t WHERE t.tgrelid='auth.users'::regclass AND NOT t.tgisinternal),
 'profile_trigger_function', (SELECT jsonb_agg(pg_get_functiondef(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='handle_new_user'),
 'policies', (SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='public' OR (schemaname='storage' AND tablename='objects')),
 'functions', (SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'configuration',p.proconfig,'acl',p.proacl,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
 'grants', (SELECT jsonb_agg(to_jsonb(g)) FROM information_schema.role_table_grants g WHERE table_schema='public' AND grantee IN ('anon','authenticated','PUBLIC')),
 'resume_bucket', (SELECT jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) FROM storage.buckets WHERE id='student-resumes')
)) AS verification_result;
ROLLBACK;
